import { createApiClient as createSharedClient } from "@sorteos/api-client";
import { ApiError, parseApiError } from "./errors";

// Consume only paths generated by the backend-owned shared package.
export function createApiClient(baseUrl: string, timeoutMs?: number, checkout = false) {
  // Generated OpenAPI paths already include /api/v1. Config is versioned,
  // whereas openapi-fetch needs the origin to avoid /api/v1/api/v1/… .
  const configuredUrl = new URL(baseUrl);
  if (configuredUrl.pathname.replace(/\/$/, "") !== "/api/v1" || !["http:", "https:"].includes(configuredUrl.protocol) || configuredUrl.username || configuredUrl.password || configuredUrl.search || configuredUrl.hash) {
    throw new Error("La URL del cliente debe terminar en /api/v1 y no incluir credenciales.");
  }
  const origin = checkout && typeof window !== "undefined" && process.env.NEXT_PUBLIC_CHECKOUT_PROXY_ENABLED === "true"
    ? window.location.origin : configuredUrl.origin;
  const client = createSharedClient(origin);
  client.use({
    onRequest: ({ request }) => new Request(request, { cache: "no-store", ...(timeoutMs ? { signal: AbortSignal.any([request.signal, AbortSignal.timeout(timeoutMs)]) } : {}) }),
    onResponse: async ({ response }) => {
      if (!response.ok) {
        const body: unknown = await response.clone().json().catch(() => null);
        throw parseApiError(body, response.status, response.headers.get("X-Request-Id"));
      }
    },
    onError: () => new ApiError("NETWORK_ERROR", 0),
  });
  return client;
}
